create or replace function aitu_private.create_student_profile() returns trigger language plpgsql security definer set search_path='' as $$ declare chosen_username text:=lower(trim(new.raw_user_meta_data->>'username')); chosen_name text:=nullif(trim(new.raw_user_meta_data->>'name'),''); chosen_group text:=coalesce(new.raw_user_meta_data->>'group_number',''); begin if new.email is null or lower(new.email) !~ '^[0-9]{6}@astanait\.edu\.kz$' then raise exception 'aitu_invalid_student_email'; end if; if chosen_username is null or chosen_username !~ '^[a-z][a-z0-9_]{2,23}$' then chosen_username:='student_'||substr(replace(new.id::text,'-',''),1,16); end if; if chosen_group !~ '^[0-9]{2}$' then chosen_group:=''; end if; if chosen_name is null then chosen_name:=split_part(new.email,'@',1); end if; insert into aitu_private.student_accounts(user_id,student_code) values(new.id,split_part(new.email,'@',1)); insert into public.aitu_profiles(id,username,name,program_code,course,group_number) values(new.id,chosen_username,left(chosen_name,60),coalesce(new.raw_user_meta_data->>'program_code','6B07102'),coalesce(nullif(new.raw_user_meta_data->>'course','')::smallint,1),chosen_group); return new; end; $$; revoke all on function aitu_private.create_student_profile() from public,anon,authenticated;
